/** Original protocol replay, without the excluded t3 business adapter registry/orchestrator. */
export const makeClaudeNativeReplayAdapter = Effect.fn("makeClaudeNativeReplayAdapter")(function* (
  input: ProviderReplayTranscript,
  options: { readonly replayGate?: ProviderReplayGate } = {},
) {
  const transcript = yield* decodeClaudeAgentSdkReplayTranscript(input).pipe(
    Effect.mapError((cause) => new ClaudeReplayTranscriptDecodeError({ ...metadataFromTranscript(input), cause })),
  );
  const fixture = yield* makePmNativeTestHost({
    driver: "claude", instanceId: ClaudeAdapterV2.CLAUDE_DEFAULT_INSTANCE_ID, cwd: sanitizedReplayCwd(transcript.scenario),
  });
  return yield* Effect.gen(function* () {
    const temporary = yield* writeReplayTaskOutputFiles(transcript);
    const queryRunner = yield* ClaudeAdapterV2.ClaudeAgentSdkQueryRunner;
    const continuations = yield* Effect.acquireRelease(Queue.unbounded<ProviderContinuationRequest>(), Queue.shutdown);
    const adapter = yield* ClaudeAdapterV2.makeClaudeAdapterV2({
      instanceId: ClaudeAdapterV2.CLAUDE_DEFAULT_INSTANCE_ID, settings: DEFAULT_CLAUDE_SETTINGS,
      environment: { ...fixture.context.env, CLAUDE_CODE_TMPDIR: temporary },
      attachmentsDir: fixture.serverConfig.attachmentsDir,
      fileSystem: yield* FileSystem.FileSystem, path: yield* Path.Path, crypto: yield* Crypto.Crypto,
      idAllocator: yield* IdAllocator.IdAllocatorV2, queryRunner,
      continuationRequests: { offer: (request) => Queue.offer(continuations, request).pipe(Effect.asVoid) },
    });
    return { adapter, fixture, continuations, assertComplete: queryRunner.assertComplete };
  }).pipe(Effect.provide(Layer.mergeAll(fixture.layer, layerClaudeAgentSdkReplay(transcript, options))));
});
